import random

def choose_person_from_period(period):
    if period == '1800':
        people = ['Napoleon Bonaparte', 'Victor Hugo', 'Edgar Allan Poe']

    elif period == '1900':
        people = ["Marie Curie", "Niels Bohr", "Max Planck"]

    else:
        raise ValueError('Invalid period')

    choice = random.choice(people)
    return {choice: period}

def main():
    people = []

    for i in range(3):
        periods = ['1800', '1900']
        person = choose_person_from_period(random.choice(periods))
        people.append(person)

